// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2, ERC20, SafeTransferLib} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    MakerContract maker;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        maker = new MakerContract();
    }

    // minimal ERC20 surface so SafeTransferLib low-level calls succeed
    function transfer(address, uint256) external pure returns (bool) { return true; }
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
    function approve(address, uint256) external pure returns (bool) { return true; }

    function testFuzz_property(uint256 duration, uint256 expiration, address filler) public {
        duration = bound(duration, 1, 9999 days);
        vm.assume(filler != address(0) && filler != address(maker) && filler != address(c) && filler != address(this));
        expiration = bound(expiration, block.timestamp + 1, block.timestamp + 365 days);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: true,
            isLong: true,
            baseAsset: address(this),
            strike: 0,
            premium: 0,
            duration: duration,
            expiration: expiration,
            nonce: 0,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes memory sig = new bytes(0);
        uint256[] memory floorAssetTokenIds = new uint256[](0);

        vm.prank(filler);
        c.fillOrder(order, sig, floorAssetTokenIds);

        bytes32 orderHash = c.hashOrder(order);
        bytes32 oppositeHash = c.hashOppositeOrder(order);
        uint256 takerPositionId = uint256(oppositeHash);

        // Rule: for a long order the expiry is recorded ONLY under the long-side key;
        // the taker's own position id must never carry an expiration.
        assertTrue(
            c.positionExpirations(uint256(orderHash)) == block.timestamp + duration &&
            c.positionExpirations(takerPositionId) == 0,
            "expiry must be recorded only at the long-side key, not at the taker positionId"
        );
    }
}

contract MakerContract {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e; // EIP-1271 magic value: always accepts the order
    }
}
